import React, { useLayoutEffect, useRef, useState } from 'react';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { useFocusRing } from '../../core/hooks/useFocusRing.js';
import type { CSSFocusStylesObject } from '../../core/hooks/useFocusRing.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { WithChildren } from '../../core/types/with-children.js';
import { getFirstFocusableChild } from '../../core/utils/focus-management/get-first-focusable-child.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';

export interface TabPanelProps
  extends WithChildren,
    DOMProps,
    AriaLabelingProps,
    StylingProps,
    DataTestId {
  /**
   * Whether the tab panel is disabled.
   * If true, its content is not rendered.
   */
  disabled: boolean;
  /** The overflow behavior of the tab panel. */
  panelOverflow: 'hidden' | 'scroll-y';
}

// #region StyledComponents
const StyledTabPanel = /* @__PURE__ */ styled('div')<{
  $focusStyle?: CSSFocusStylesObject;
  $panelOverflow: 'hidden' | 'scroll-y';
}>(({ $focusStyle, $panelOverflow }) => {
  const overflowBehavior =
    $panelOverflow === 'hidden'
      ? ({ overflow: 'hidden' } as const)
      : ({ overflowY: 'auto' } as const);

  return {
    ...$focusStyle,
    ...overflowBehavior,
    width: '100%',
    height: '100%',
    boxSizing: 'border-box',
    paddingTop: Spacings.Size16,
  };
});
// #endregion

/**
 * TabPanel component, used to display the content of a tab.
 */
export const TabPanel = (props: TabPanelProps) => {
  const {
    children,
    disabled,
    panelOverflow,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...restProps
  } = props;
  const ref = useRef<HTMLDivElement>(null);

  const { focusProps, focusStyles } = useFocusRing();
  const [hasFocusableChildren, setHasFocusableChildren] =
    useState<boolean>(false);

  // Check if the tab panel has focusable children to focus on them instead of the panel per a11y rules
  useLayoutEffect(() => {
    if (ref.current) {
      setHasFocusableChildren(getFirstFocusableChild(ref.current) !== null);
    }
  }, [children]);

  return (
    <StyledTabPanel
      data-testid={dataTestId}
      className={consumerClassName}
      style={consumerStyle}
      ref={ref}
      {..._mergeProps(focusProps, restProps)}
      $focusStyle={focusStyles}
      $panelOverflow={panelOverflow}
      tabIndex={hasFocusableChildren ? -1 : 0}
    >
      {!disabled && <div>{children}</div>}
    </StyledTabPanel>
  );
};
TabPanel['displayName'] = 'TabPanel';
